function loginV(){return `<div class="login"><div class="l"><div class="logo"><b style="background:#fff;color:#4338ca">EG</b>ExamGuard</div><h1 style="font-size:44px;line-height:1.1">Fair exams, even when the network isn’t.</h1><p style="opacity:.85;max-width:460px">Create, run, monitor and grade online examinations with server-authoritative timers, offline-safe autosave and verifiable result reports.</p><div class="feat"><span>Failure-resilient attempts</span><span>Dispute resolution</span><span>Difficulty-balanced papers</span><span>Verifiable PDF reports</span></div></div>
<div class="r"><div style="max-width:400px;width:100%"><h2>Sign in</h2><p class="mu" style="margin:6px 0 18px">Pick a demo role to explore. Each role sees a different workspace.</p>
${[["Candidate","🎓","Take exams, view results, verify reports"],["Examiner","📝","Create exams, monitor, grade, publish"],["Administrator","🛡️","Manage users, roles and permissions"]].map(r=>`<button class="card role" onclick="login('${r[0]}')"><i>${r[1]}</i><span><b>${r[0]}</b><br><span class="mu sm">${r[2]}</span></span></button>`).join("")}
<p class="mu sm" style="margin-top:14px">Permissions are enforced on the server. This preview uses test data only.</p></div></div></div>`}
